import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture, uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  const metalTexture = ctx.textureLoader.load(
    '/prism-assets/chrome/brushed-metal.map.png'
  );
  metalTexture.colorSpace = THREE.SRGBColorSpace;

  const aspectRatio = 512 / 320;
  const geometry = new THREE.PlaneGeometry(aspectRatio, 1);

  const mat = new MeshBasicNodeMaterial();
  mat.colorNode = texture(metalTexture, uv());

  const mesh = new THREE.Mesh(geometry, mat);
  group.add(mesh);

  if (config.scenePosition) {
    const pos = config.scenePosition;
    group.position.set(pos.x ?? 0, pos.y ?? 0, pos.z ?? 0);
    if (pos.rotationXYZ) {
      const [rx, ry, rz] = pos.rotationXYZ;
      group.rotation.order = 'XYZ';
      group.rotation.set(rx, ry, rz);
    }
    if (pos.scaleXYZ) {
      const [sx, sy, sz] = pos.scaleXYZ;
      group.scale.set(sx, sy, sz);
    }
  }

  group.userData.cleanup = () => {
    geometry.dispose();
    mat.dispose();
    metalTexture.dispose();
  };

  group.userData.handlers = {};

  return group;
}
